// Initialize global mock object
var SystemMocks = {};

// Helper to fetch JSON and extend SystemMocks
function loadMocks(notify = false) {
    Promise.all([
        fetch('mock_data.json').then(res => res.json()),
        fetch('mock_scenes.json').then(res => res.json()),
        fetch('mock_human.json').then(res => res.json()),
        fetch('mock_listopc.json').then(res => res.json()),
        fetch('mock_tabelas.json').then(res => res.json()).catch(() => []),
        fetch('mock_forms.json').then(res => res.json()).catch(() => [])
    ]).then(([systemData, sceneData, humanData, listOpcData, tabelasData, formsData]) => {
        // Merge system data
        SystemMocks = Object.assign(SystemMocks, systemData);
        // Merge scene data
        SystemMocks.scene = sceneData;
        // Merge human data
        SystemMocks.human = humanData;
        // Merge list options data
        SystemMocks.listopc = listOpcData;
        // Merge tables data
        SystemMocks.tabelas = tabelasData;
        // Merge forms data
        SystemMocks.forms = formsData;
        console.log('Mocks loaded:', SystemMocks);
        if (notify) alert('Variáveis atualizadas com sucesso!');
    }).catch(err => {
        console.warn('Error loading mocks:', err);
        if (notify) alert('Erro ao atualizar variáveis: ' + err);
    });
}

// Initial load
loadMocks();

// Auto-update mocks every 60 seconds
setInterval(() => {
    loadMocks(false);
}, 60000);

