// Helper function to handle arguments.
// If the argument comes from a variable block (sc_variable_getter), it returns it as is.
// If it's a string literal, it wraps it in quotes.
function getScArg(block, name, generator) {
    var targetBlock = block.getInputTargetBlock(name);
    var code = generator.valueToCode(block, name, generator.ORDER_NONE) || '""';

    // Clean up code if it was wrapped in parentheses by other generators
    code = code.replace(/^\((.*)\)$/, '$1');

    // Check if the target block is our variable getter
    if (targetBlock && (targetBlock.type === 'sc_session_var' || targetBlock.type === 'sc_mem_unescape' || targetBlock.type === 'sc_mem_numeric' || targetBlock.type === 'sc_mem_money' || targetBlock.type === 'sc_mem_position' || targetBlock.type === 'sc_mem_date' || targetBlock.type === 'sc_mem_json' || targetBlock.type === 'sc_system_var')) {
        // It's a variable, return as is (e.g. %nome% or $nome)
        // Remove any extra quotes if the generator added them (though valueToCode usually returns string)
        return code.replace(/^['"]|['"]$/g, '');
    }

    // If it's a raw string (e.g. "texto"), ensure it has double quotes
    // The default generator might return 'string' or "string". We want "string".
    var needsQuotes = !code.startsWith('"');

    // If it starts with % or $, it might be a simple variable or a complex expression
    if (code.startsWith('%') || code.startsWith('$')) {
        // If it contains a space or arithmetic operators, it's likely an expression that needs quotes
        if (code.includes(' ') || code.includes('+') || code.includes('-') || code.includes('*') || code.includes('/')) {
            needsQuotes = true;
        } else {
            needsQuotes = false;
        }
    }

    if (needsQuotes) {
        // If it's a number, don't quote it
        if (code !== '' && !isNaN(Number(code))) {
            return code;
        }

        // If it's not a var and not quoted, quote it.
        // However, valueToCode for strings usually returns "'text'".
        // We strip single quotes and add double quotes.
        if (code.startsWith("'") && code.endsWith("'")) {
            code = code.substring(1, code.length - 1);
        }
        return '"' + code + '"';
    }

    // If it's already double quoted, keep it.
    return code;
}

// Override the scrub_ method to use '#' for comments instead of '//'
javascript.javascriptGenerator.scrub_ = function (block, code, opt_thisOnly) {
    var commentCode = '';
    // Only collect comments for blocks that aren't inline.
    if (!block.outputConnection || !block.outputConnection.targetConnection) {
        // Collect comment for this block.
        var comment = block.getCommentText();
        if (comment) {
            comment = Blockly.utils.string.wrap(comment, this.COMMENT_WRAP - 3);
            if (block.getProcedureDef) {
                // Use a comment function for function definitions.
                commentCode += this.prefixLines(comment + '\n', '/** ', ' * ', ' */\n');
            } else {
                // - - - - MODIFIED HERE - - - -
                // Use '#' for single line comments.
                commentCode += this.prefixLines(comment + '\n', '# ');
                // - - - - - - - - - - - - - - -
            }
        }
        // Collect comments for all value arguments.
        // Don't collect comments for nested statements.
        for (var i = 0; i < block.inputList.length; i++) {
            // Blockly.inputTypes.VALUE is assumed to be 1. If inputTypes is undefined, use 1.
            if (block.inputList[i].type === (Blockly.inputTypes ? Blockly.inputTypes.VALUE : 1)) {
                var childBlock = block.inputList[i].connection.targetBlock();
                if (childBlock) {
                    var comment = this.allNestedComments(childBlock);
                    if (comment) {
                        // - - - - MODIFIED HERE - - - -
                        commentCode += this.prefixLines(comment, '# ');
                        // - - - - - - - - - - - - - - -
                    }
                }
            }
        }
    }
    var nextBlock = block.nextConnection && block.nextConnection.targetBlock();
    var nextCode = opt_thisOnly ? '' : this.blockToCode(nextBlock);
    return commentCode + code + nextCode;
};

// 1. Categoria: Mensagens e Interação
// Override standard 'text' block to encode emojis as HTML entities
javascript.javascriptGenerator.forBlock['text'] = function (block, generator) {
    var code = block.getFieldValue('TEXT');
    // Encode emojis and non-ASCII chars to HTML entities
    var result = '';
    for (var i = 0; i < code.length; i++) {
        var charCode = code.codePointAt(i);
        if (charCode > 127) {
            result += '&#' + charCode + ';';
            // If surrogate pair, skip next code unit
            if (charCode > 0xFFFF) {
                i++;
            }
        } else {
            result += code[i];
        }
    }
    return ['"' + result + '"', generator.ORDER_ATOMIC];
};

