javascript.javascriptGenerator.forBlock['sc_opc'] = function (block, generator) {
    var mem = block.getFieldValue('MEM');
    var listCode = block.getFieldValue('LIST_CODE');
    var gotoScene = block.getFieldValue('GOTO');
    var order = block.getFieldValue('ORDER');
    var typeOp = block.getFieldValue('TYPE_OP');
    var format = block.getFieldValue('FORMAT');
    var separator = block.getFieldValue('SEPARATOR');
    var extraOp = getScArg(block, 'EXTRA_OP', generator);
    var extraGoto = block.getFieldValue('EXTRA_GOTO');

    // ::opc(mem, list, goto, order, type, format, sep, extra_op, extra_goto)
    var args = [
        '"' + mem + '"',
        '"' + listCode + '"',
        (gotoScene ? '"' + gotoScene + '"' : '""'),
        order,
        typeOp,
        '"' + format + '"',
        separator
    ];

    // Optional args handling
    if (extraOp && extraOp !== '""') {
        args.push(extraOp);
        if (extraGoto && extraGoto !== '') {
            args.push('"' + extraGoto + '"');
        }
    } else if (extraGoto && extraGoto !== '') {
        // If extraOp is empty but extraGoto is set, we might need a placeholder or logic.
        // Assuming extraGoto usually depends on extraOp.
        // If the user wants just a go-to without extra op text, it might be weird.
        // Generating empty string for extraOp to reach extraGoto position
        args.push('""');
        args.push('"' + extraGoto + '"');
    }

    return '::opc(' + args.join(', ') + ')\n';
};

