javascript.javascriptGenerator.forBlock['sc_se'] = function (block, generator) {
    var cond = generator.valueToCode(block, 'COND', generator.ORDER_NONE) || '""';
    var trueAct = generator.statementToCode(block, 'TRUE_ACT').trim();

    var falseAct = '';
    if (block.getInput('FALSE_ACT')) {
        falseAct = generator.statementToCode(block, 'FALSE_ACT').trim();
    }

    // ::se(condicao ? verdadeiro ; falso)
    // If falseAct is empty, omit the separator
    if (!falseAct) {
        return '::se(' + cond + ' ? ' + trueAct + ')\n';
    }
    return '::se(' + cond + ' ? ' + trueAct + ' ; ' + falseAct + ')\n';
};

javascript.javascriptGenerator.forBlock['sc_ign'] = function (block, generator) {
    var elements = [];
    var count = block.itemCount_ || 0;
    // Fallback if itemCount_ is undefined but has old static inputs?
    // The new block definition uses itemCount_, old blocks might need migration or just rely on 0 defaults if opened in new editor.
    // Actually, distinct blocks. New instance will have itemCount_.
    for (var i = 0; i < count; i++) {
        var arg = getScArg(block, 'VAL' + i, generator);
        elements.push(arg);
    }
    return '::ign(' + elements.join(', ') + ')\n';
};

