javascript.javascriptGenerator.forBlock['sc_mth'] = function (block, generator) {
    var formula = getScArg(block, 'FORMULA', generator);
    var varName = block.getFieldValue('VAR_NAME');

    // If formula is empty string or quoted empty string, just generate ::mth()
    if (!formula || formula === '""' || formula === "''") {
        return '::mth()\n';
    }

    // ::mth(formula, varname)
    if (block.hasVar_ && varName && varName !== '""' && varName !== "''") {
        return '::mth(' + formula + ', "' + varName + '")\n';
    }

    return '::mth(' + formula + ')\n';
};

