javascript.javascriptGenerator.forBlock['math_arithmetic'] = function (block, generator) {
    // Standard operators
    var OPERATORS = {
        'ADD': [' + ', generator.ORDER_ADDITION],
        'MINUS': [' - ', generator.ORDER_SUBTRACTION],
        'MULTIPLY': [' * ', generator.ORDER_MULTIPLICATION],
        'DIVIDE': [' / ', generator.ORDER_DIVISION],
    };

    var targetA = block.getInputTargetBlock('A');
    var targetB = block.getInputTargetBlock('B');

    // If either side is NULL (not connected), return empty string so sc_mth can handle it
    if (!targetA || !targetB) {
        return ['', generator.ORDER_ATOMIC];
    }

    var opValue = block.getFieldValue('OP');
    var tuple = OPERATORS[opValue];
    var operator = tuple[0];
    var order = tuple[1];

    var argument0 = getScArg(block, 'A', generator);
    var argument1 = getScArg(block, 'B', generator);

    var code = argument0 + operator + argument1;
    return [code, order];
};

