/**
 * Helper to get options from the global SystemMocks object.
 * @param {string} key The key in SystemMocks (e.g., 'msg', 'arq').
 * @returns {Array} Array of [Description, ID] pairs.
 */
function getSysOptions(key) {
    // Check if SystemMocks is defined (it should be loaded from mock_data.js)
    if (typeof SystemMocks === 'undefined' || !SystemMocks[key]) {
        return [['Carregando...', '']];
    }
    return SystemMocks[key].map(function (item) {
        var desc = item.desc || item.Tabela || item.Form || item.id || "Sem nome";
        var id = item.id || item.ID || "";
        return [desc, id];
    });
}

