// Override standard text_join to produce concatenated string literal: "Part1Part2"
javascript.javascriptGenerator.forBlock['text_join'] = function (block, generator) {
    var elements = [];
    for (var i = 0; i < block.itemCount_; i++) {
        var code = generator.valueToCode(block, 'ADD' + i, generator.ORDER_NONE) || '';
        // If code is quoted string '"text"', strip quotes
        if (code.startsWith('"') && code.endsWith('"')) {
            code = code.substring(1, code.length - 1);
        } else if (code.startsWith("'") && code.endsWith("'")) {
            code = code.substring(1, code.length - 1);
        }
        elements.push(code);
    }
    // Join all parts and wrap in double quotes
    var code = '"' + elements.join('') + '"';
    return [code, generator.ORDER_ATOMIC];
};

