// Mixin object for the mutator
var SC_IGN_MUTATOR_MIXIN = {
    mutationToDom: function () {
        var container = Blockly.utils.xml.createElement('mutation');
        container.setAttribute('items', this.itemCount_);
        return container;
    },
    domToMutation: function (xmlElement) {
        this.itemCount_ = parseInt(xmlElement.getAttribute('items'), 10);
        this.updateShape_();
    },
    decompose: function (workspace) {
        var containerBlock = workspace.newBlock('sc_ign_container');
        containerBlock.initSvg();
        var connection = containerBlock.getInput('STACK').connection;
        for (var i = 0; i < this.itemCount_; i++) {
            var itemBlock = workspace.newBlock('sc_ign_item');
            itemBlock.initSvg();
            connection.connect(itemBlock.previousConnection);
            connection = itemBlock.nextConnection;
        }
        return containerBlock;
    },
    compose: function (containerBlock) {
        var itemBlock = containerBlock.getInputTargetBlock('STACK');
        var connections = [];
        while (itemBlock) {
            connections.push(itemBlock.valueConnection_);
            itemBlock = itemBlock.nextConnection && itemBlock.nextConnection.targetBlock();
        }
        for (var i = 0; i < this.itemCount_; i++) {
            var connection = this.getInput('VAL' + i).connection.targetConnection;
            if (connection && connections.indexOf(connection) == -1) {
                connection.disconnect();
            }
        }
        this.itemCount_ = connections.length;
        this.updateShape_();
        for (var i = 0; i < this.itemCount_; i++) {
            if (connections[i]) {
                this.getInput('VAL' + i).connection.connect(connections[i]);
            }
        }
    },
    saveConnections: function (containerBlock) {
        var itemBlock = containerBlock.getInputTargetBlock('STACK');
        var i = 0;
        while (itemBlock) {
            var input = this.getInput('VAL' + i);
            itemBlock.valueConnection_ = input && input.connection.targetConnection;
            i++;
            itemBlock = itemBlock.nextConnection && itemBlock.nextConnection.targetBlock();
        }
    },
    updateShape_: function () {
        // Delete everything.
        if (this.getInput('EMPTY')) {
            this.removeInput('EMPTY');
        }
        var i = 0;
        while (this.getInput('VAL' + i)) {
            this.removeInput('VAL' + i);
            i++;
        }
        // Rebuild.
        if (this.itemCount_ == 0) {
            this.appendDummyInput('EMPTY')
                .appendField("Nenhum valor");
        } else {
            for (var i = 0; i < this.itemCount_; i++) {
                var input = this.appendValueInput('VAL' + i)
                    .setCheck(['String', 'Number', 'sc_session_var', 'sc_system_var']);
            }
        }
    }
};

// Register the mutator extension
Blockly.Extensions.registerMutator(
    'sc_ign_mutator',
    SC_IGN_MUTATOR_MIXIN,
    function () {
        // Helper function (Init)
        this.itemCount_ = 2;
        this.updateShape_();
    },
    ['sc_ign_item']
);

