var SC_SE_MUTATOR_MIXIN = {
    mutationToDom: function () {
        var container = Blockly.utils.xml.createElement('mutation');
        if (this.hasElse_) {
            container.setAttribute('else', 1);
        }
        return container;
    },
    domToMutation: function (xmlElement) {
        this.hasElse_ = parseInt(xmlElement.getAttribute('else'), 10) == 1;
        this.updateShape_();
    },
    decompose: function (workspace) {
        var containerBlock = workspace.newBlock('sc_se_mutator_container');
        containerBlock.initSvg();
        var connection = containerBlock.getInput('STACK').connection;
        if (this.hasElse_) {
            var elseBlock = workspace.newBlock('sc_se_mutator_else');
            elseBlock.initSvg();
            connection.connect(elseBlock.previousConnection);
        }
        return containerBlock;
    },
    compose: function (containerBlock) {
        var clauseBlock = containerBlock.getInputTargetBlock('STACK');
        this.hasElse_ = false;
        var elseStatementConnection = null;
        while (clauseBlock) {
            if (clauseBlock.type == 'sc_se_mutator_else') {
                this.hasElse_ = true;
                elseStatementConnection = clauseBlock.valueConnection_;
            }
            clauseBlock = clauseBlock.nextConnection && clauseBlock.nextConnection.targetBlock();
        }
        this.updateShape_();
        // Reconnect if needed
        if (this.hasElse_ && elseStatementConnection) {
            var input = this.getInput('FALSE_ACT');
            if (input && input.connection) {
                input.connection.connect(elseStatementConnection);
            }
        }
    },
    saveConnections: function (containerBlock) {
        var clauseBlock = containerBlock.getInputTargetBlock('STACK');
        while (clauseBlock) {
            if (clauseBlock.type == 'sc_se_mutator_else') {
                var inputElse = this.getInput('FALSE_ACT');
                clauseBlock.valueConnection_ = inputElse && inputElse.connection.targetConnection;
            }
            clauseBlock = clauseBlock.nextConnection && clauseBlock.nextConnection.targetBlock();
        }
    },
    updateShape_: function () {
        if (this.hasElse_) {
            if (!this.getInput('FALSE_ACT')) {
                this.appendStatementInput('FALSE_ACT')
                    .appendField("Senão");
            }
        } else {
            if (this.getInput('FALSE_ACT')) {
                this.removeInput('FALSE_ACT');
            }
        }
    }
};

Blockly.Extensions.registerMutator(
    'sc_se_mutator',
    SC_SE_MUTATOR_MIXIN,
    function () {
        this.hasElse_ = false;
    },
    ['sc_se_mutator_else']
);

