Blockly.Extensions.register('sc_enforce_single_statement', function () {
    this.setOnChange(function (e) {
        if (this.workspace.isDragging && this.workspace.isDragging()) {
            return;
        }
        var enforceSingle = function (block, inputName) {
            if (!block.getInput(inputName)) return; // Safety check
            var first = block.getInputTargetBlock(inputName);
            if (first && first.getNextBlock()) {
                var next = first.getNextBlock();
                next.unplug(true);
            }
        };
        enforceSingle(this, 'TRUE_ACT');
        enforceSingle(this, 'FALSE_ACT');
    });
});
